extend schema
  @link(url: "https://specs.apollo.dev/federation/v2.3",
        import: ["@key", "@shareable"])

type Query {
  model: Model!
  part(id: ID!): Part
  requirement(id: ID!): Requirement
}

type Model {
  version: Int!
  text: String!
  roots: [Part!]!
  parts: [Part!]!
  requirements: [Requirement!]!
  verificationCases: [VerificationCase!]!
}

type Part @key(fields: "id") {
  id: ID!
  shortName: String
  name: String!
  definition: String!
  doc: String
  attributes: [Attribute!]!
  ports: [Port!]!
  parts: [Part!]!
  connections: [Connection!]!
  satisfies: [Requirement!]!
}

type Attribute @shareable {
  name: String!
  value: Float
  unit: String
  editable: Boolean!
  expression: String
}

type Port @shareable {
  name: String!
  direction: Direction!
}

enum Direction { IN OUT INOUT }

type Connection @shareable {
  id: ID!
  from: ID!
  fromPort: String!
  to: ID!
  toPort: String!
}

type Requirement @key(fields: "id") {
  id: ID!
  shortName: String
  name: String!
  text: String
  subject: Part
  quantity: String
  comparison: Comparison
  limit: Float
  limitUnit: String
  limitEditable: Boolean!
  derivedFrom: [Requirement!]!
  derives: [Requirement!]!
  satisfiedBy: [Part!]!
  verifiedBy: [VerificationCase!]!
}

enum Comparison { GE GT LE LT EQ }

type VerificationCase @key(fields: "id") {
  id: ID!
  shortName: String
  name: String!
  verifies: [Requirement!]!
}

type Mutation {
  setAttribute(partId: ID!, name: String!, value: Float!): Part!
  setLimit(requirementId: ID!, value: Float!): Requirement!
  resetModel: Model!
}

type Subscription {
  modelChanged: Int!
}

extend schema
  @link(url: "https://specs.apollo.dev/federation/v2.3",
        import: ["@key", "@external", "@requires"])

type Part @key(fields: "id") {
  id: ID!
  name: String! @external
  attributes: [Attribute!]! @external
  parts: [Part!]! @external
  connections: [Connection!]! @external
  capacity: Float
    @requires(fields: "attributes { name value } parts { id name attributes { name value } } connections { from to }")
  bottleneck: [Part!]!
    @requires(fields: "parts { id name attributes { name value } } connections { from to }")
}

type Attribute {
  name: String! @external
  value: Float @external
}

type Connection {
  from: ID! @external
  to: ID! @external
}

type VerificationCase @key(fields: "id", resolvable: false) {
  id: ID!
  shortName: String @external
}

type Requirement @key(fields: "id") {
  id: ID!
  quantity: String @external
  comparison: Comparison @external
  limit: Float @external
  subject: Part @external
  verifiedBy: [VerificationCase!]! @external
  verdict: Verdict!
    @requires(fields: "quantity comparison limit verifiedBy { shortName } subject { id name attributes { name value } parts { id name attributes { name value } } connections { from to } }")
  verdictReason: String!
    @requires(fields: "quantity comparison limit verifiedBy { shortName } subject { id name attributes { name value } parts { id name attributes { name value } } connections { from to } }")
}

enum Comparison { GE GT LE LT EQ }
enum Verdict { PASS FAIL INCONCLUSIVE ERROR }

extend schema
  @link(url: "https://specs.apollo.dev/federation/v2.3",
        import: ["@key"])

type Query {
  document: Document!
}

type Document {
  version: Int!
  nodes: [Node!]!
}

type Node {
  id: ID!
  kind: NodeKind!
  number: String
  text: String
  requirement: Requirement
  children: [Node!]!
}

enum NodeKind { HEADING PROSE REQUIREMENT }

type Requirement @key(fields: "id") {
  id: ID!
  documentNumber: String
  included: Boolean!
}

type Mutation {
  moveNode(id: ID!, parentId: ID, index: Int!): Document!
  insertHeading(aboveId: ID!, text: String!): Document!
  addProse(parentId: ID, index: Int!, text: String!): Document!
  editText(id: ID!, text: String!): Document!
  excludeRequirement(requirementId: ID!): Document!
  includeRequirement(requirementId: ID!): Document!
  resetDocument: Document!
}

type Subscription {
  documentChanged: Int!
}

